def program(xs):
    a = list(xs)                     # work on a copy
    n = len(a)
    if n < 2:
        return a

    # length of the initial run of the first value
    run_len = 1
    while run_len < n and a[run_len] == a[0]:
        run_len += 1

    # ----- case 1: initial run longer than 1 -----
    if run_len > 1:
        if run_len > 2:
            # swap first element with the element after the run
            a[0], a[run_len] = a[run_len], a[0]
        else:  # run_len == 2
            # swap the two elements that follow the first one
            if n > 2:
                a[1], a[2] = a[2], a[1]
        return a

    # ----- case 2: first element appears later -----
    if a[0] in a[1:]:
        next_idx = a.index(a[0], 1)           # next occurrence of a[0]
        seg = a[1:next_idx]                    # slice between first and that occurrence
        if len(seg) >= 2 and seg[0] == seg[1]:
            # there is a run of identical numbers at the start of seg
            run = 1
            while run < len(seg) and seg[run] == seg[0]:
                run += 1
            k = run + 1                       # size of prefix to rotate left
            a[:k] = a[1:k] + [a[0]]           # rotate left the prefix (first element moves after the run)
        else:
            # simple swap of positions 1 and 2
            if n > 2:
                a[1], a[2] = a[2], a[1]
        return a

    # ----- case 3: first element is unique -----
    # find first place where two consecutive values are equal
    repeat_idx = None
    for i in range(1, n):
        if a[i] == a[i-1]:
            repeat_idx = i
            break
    if repeat_idx is not None and repeat_idx + 1 < n:
        # swap first element with the element after the repeated pair
        a[0], a[repeat_idx + 1] = a[repeat_idx + 1], a[0]
    else:
        # fallback: swap first with last
        a[0], a[-1] = a[-1], a[0]
    return a

