def program(xs):
    """Transform the list according to the discovered rule.
    - If the list has 4 or more elements, swap the first two elements with the next two.
    - If the list has exactly 3 elements, rotate it right by one position.
    - For lengths 0, 1, or 2, return the list unchanged.
    """
    n = len(xs)
    if n >= 4:
        # swap the first pair with the second pair
        return xs[2:4] + xs[0:2] + xs[4:]
    elif n == 3:
        # rotate right by one
        return [xs[2], xs[0], xs[1]]
    else:
        # 0, 1, or 2 elements stay the same
        return xs

