def program(xs):
    n = len(xs)
    if n < 2:
        return []
    # find first decrease
    start = None
    for i in range(1, n):
        if xs[i] < xs[i-1]:
            start = i
            break
    if start is None:
        # no decrease, identity
        return xs[:]
    # begin result with the decreasing element and the next one (if any)
    res = [xs[start]]
    if start + 1 < n:
        res.append(xs[start+1])
    # continue adding only non‑decreasing elements
    last = res[-1]
    for j in range(start+2, n):
        if xs[j] >= last:
            res.append(xs[j])
            last = xs[j]
    return res

