def rotate_left(lst, k):
    n = len(lst)
    if n == 0:
        return lst
    k %= n
    return lst[k:] + lst[:k]

def program(xs):
    if not xs:
        return xs
    mn = min(xs)
    p = xs.index(mn)               # first occurrence of the minimum
    n = len(xs)
    if p == n - 1:                 # minimum already at the end -> no change
        k = 0
    else:
        k = (p + 1) % n            # rotate so that element after the first minimum becomes first
    return rotate_left(xs, k)

