    if n == 0:
        return []
    cnt = Counter(xs)
    global_min = min(xs)
    global_max = max(xs)
    result = []
    for i, x in enumerate(xs):
        # rule 1: duplicate
        if cnt[x] > 1:
            continue
        # rule 2: interior local extremum
        if 0 < i < n - 1:
            left, right = xs[i - 1], xs[i + 1]
            if (x < left and x < right) or (x > left and x > right):
                continue
        # rule 3: leftmost global minimum
        if i == 0:
            if x == global_min:
                continue
        # rule 4: rightmost global min or max
        if i == n - 1:
            if x == global_min or x == global_max:
                continue
        result.append(x)
    return result

