def program(xs):
    n = len(xs)
    # For empty or single‑element lists the result is all zeros
    if n <= 1:
        return [0] * n
    max_diff = -1
    best_i, best_j = 0, 1
    for i in range(n - 1):
        xi = xs[i]
        for j in range(i + 1, n):
            d = abs(xi - xs[j])
            if d > max_diff:
                max_diff = d
                best_i, best_j = i, j
    result = xs[:]  # shallow copy
    result[best_i] = max_diff
    result[best_j] = max_diff
    return result

