def program(xs):
    def recurse(arr):
        n = len(arr)
        if n <= 2:
            # For 0,1,2 elements the required order is just the sorted order
            # (so the smaller element comes before the larger one when two exist).
            return sorted(arr)
        # Find the largest value
        max_val = max(arr)
        # Find the second largest distinct value (if it exists)
        sec_candidates = [v for v in arr if v != max_val]
        if sec_candidates:
            sec_val = max(sec_candidates)
        else:
            # all elements are equal; treat sec_val same as max_val
            sec_val = max_val
        # Remove one occurrence of sec_val and one of max_val, preserving order
        remaining = []
        used_sec = False
        used_max = False
        for v in arr:
            if not used_sec and v == sec_val:
                used_sec = True
                continue
            if not used_max and v == max_val:
                used_max = True
                continue
            remaining.append(v)
        # Recursively process the middle part
        return [sec_val] + recurse(remaining) + [max_val]
    return recurse(xs)

