import sys, ast

def first_change_index(arr):
    # Return the index of the element where the first direction change occurs.
    # If the list never changes direction, return len(arr) - 1.
    if len(arr) < 2:
        return len(arr) - 1
    # Determine initial direction ignoring equal neighbours.
    i = 0
    while i + 1 < len(arr) and arr[i] == arr[i + 1]:
        i += 1
    if i + 1 == len(arr):
        return len(arr) - 1
    direction = 1 if arr[i] < arr[i + 1] else -1
    # Scan forward until direction flips.
    for j in range(i + 1, len(arr) - 1):
        if arr[j] == arr[j + 1]:
            continue
        cur_dir = 1 if arr[j] < arr[j + 1] else -1
        if cur_dir != direction:
            # Change occurs at j+1; we remove up to j (inclusive).
            return j
    return len(arr) - 1

def last_change_index(arr):
    # Return the index (inclusive) of the last element to keep before the final direction change.
    if len(arr) < 2:
        return 0
    i = len(arr) - 1
    while i - 1 >= 0 and arr[i] == arr[i - 1]:
        i -= 1
    if i == 0:
        return 0
    direction = 1 if arr[i - 1] < arr[i] else -1
    for j in range(i - 1, 0, -1):
        if arr[j] == arr[j - 1]:
            continue
        cur_dir = 1 if arr[j - 1] < arr[j] else -1
        if cur_dir != direction:
            # Change occurs at j-1; we keep up to j-1.
            return j - 1
    return 0

def program(xs):
    if not xs:
        return []
    # Step 1: cut the prefix up to the first direction change.
    cut_prefix = first_change_index(xs)
    middle = xs[cut_prefix + 1:]
    if not middle:
        return []
    # Step 2: cut the suffix after the last direction change.
    cut_suffix = last_change_index(middle)
    result = middle[:cut_suffix + 1]
    return result

