def reverse_runs(arr):
    """Return arr with the order of maximal equal‑value runs reversed."""
    runs = []
    i = 0
    n = len(arr)
    while i < n:
        j = i + 1
        while j < n and arr[j] == arr[i]:
            j += 1
        runs.append(arr[i:j])
        i = j
    result = []
    for run in reversed(runs):
        result.extend(run)
    return result

